# ------------------------------------------------------- shared members
def _bundle_members(self, value, field, plural, singular, parse_child):
    if not isinstance(value, dict) or set(value) != {"root", plural}:
        raise ValueError(
            f"{field} must be a dict with exactly the keys root, {plural}"
        )
